SELECT CASE WHEN amount >= 1630 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('YEAR', paid_at) AS year_start, COUNT_IF(method = 'cash') AS cash_events, STDDEV_SAMP(amount) AS amount_stddev, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, PERCENT_RANK() OVER (PARTITION BY CASE WHEN amount >= 1630 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 DESC) AS duration_min_percent_rank FROM payments GROUP BY 1, 2;
